1	import path from "node:path";
2	import {Multiaddr, multiaddr} from "@multiformats/multiaddr";
3	import {Discv5, ENR, IDiscv5CreateOptions} from "@chainsafe/discv5";
4	import {ErrorAborted} from "@lodestar/utils";
5	import {HttpMetricsServer, RegistryMetricCreator, getHttpMetricsServer} from "@lodestar/beacon-node";
6	
7	import {GlobalArgs} from "../../options/index.js";
8	import {getBeaconConfigFromArgs} from "../../config/index.js";
9	import {getNetworkBootnodes, isKnownNetworkName, readBootnodes} from "../../networks/index.js";
10	import {onGracefulShutdown, mkdir, writeFile600Perm} from "../../util/index.js";
11	import {getVersionData} from "../../util/version.js";
12	import {initPeerIdAndEnr} from "../beacon/initPeerIdAndEnr.js";
13	import {parseArgs as parseMetricsArgs} from "../../options/beaconNodeOptions/metrics.js";
14	import {parseArgs as parseNetworkArgs} from "../../options/beaconNodeOptions/network.js";
15	import {getBeaconPaths} from "../beacon/paths.js";
16	import {BeaconArgs} from "../beacon/options.js";
17	import {initLogger} from "../beacon/handler.js";
