23	export type NetworkName =
24	  | "mainnet"
25	  | "dev"
26	  | "gnosis"
27	  | "goerli"
28	  | "ropsten"
29	  | "sepolia"
30	  | "holesky"
31	  | "chiado"
32	  | "ephemery";
33	export const networkNames: NetworkName[] = [
34	  "mainnet",
35	  "gnosis",
36	  "goerli",
37	  "ropsten",
38	  "sepolia",
39	  "holesky",
40	  "chiado",
41	  "ephemery",
42	
43	  // Leave always as last network. The order matters for the --help printout
44	  "dev",
45	];
