154	/**
155	 * Fetch weak subjectivity state from a remote beacon node
156	 */
157	export async function fetchWeakSubjectivityState(
158	  config: ChainForkConfig,
159	  logger: Logger,
160	  {checkpointSyncUrl, wssCheckpoint}: {checkpointSyncUrl: string; wssCheckpoint?: string}
161	): Promise<{wsState: BeaconStateAllForks; wsCheckpoint: Checkpoint}> {
162	  try {
163	    let wsCheckpoint: Checkpoint | null;
164	    let stateId: Slot | "finalized";
165	
166	    const api = getClient({baseUrl: checkpointSyncUrl}, {config});
167	    if (wssCheckpoint) {
168	      wsCheckpoint = getCheckpointFromArg(wssCheckpoint);
169	      stateId = wsCheckpoint.epoch * SLOTS_PER_EPOCH;
170	    } else {
171	      // Fetch current finalized state and extract checkpoint from it
172	      stateId = "finalized";
173	      wsCheckpoint = null;
174	    }
175	
176	    // getStateV2 should be available for all forks including phase0
177	    const getStatePromise = api.debug.getStateV2(stateId, "ssz");
178	
